  ('101090811', 'Dawnlit Joyeuse (Water)', 'Dawnlit Joyeuse (Water)', '{"9":"Dawnlit Joyeuse (Water)","10":"Dawnlit Joyeuse (Water)","11":"Dawnlit Joyeuse (Water)","12":"Dawnlit Joyeuse (Water)","13":"Dawnlit Joyeuse (Water)","14":"Dawnlit Joyeuse (Water)"}'::JSONB, 'long_sword', NULL, 'Dawnlit Joyeuse', 'apex_variant', 'Apex Weapon element variant: switch the element of the base version (Apex Challenge – Ruger Aidal season)', 'water', 226, 452, 0, 'White', ARRAY[1, 1]::INTEGER[], 9, 14, TRUE, TRUE, 'Apex Challenge – Ruger Aidal season', '{"name":"Long Sword Mastery","description":"While this weapon is equipped, damage dealt to radiant monsters increases by 8%. For each 1 Spirit Gauge level gained, damage dealt to radiant monsters increases by an additional 1.4% for the rest of the hunt, up to 3 stacks. (Season 0 only)","icon":"/images/weapons/AwakeIEntryIcon/AwakeIEntryIcon_Swo_06.png"}'::JSONB, '{"unlock_rarities":[10,11,12,13,14],"options":[["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"],["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"],["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"],["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"],["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"]]}'::JSONB, '/images/weapons/WeaponIcon/LongSword/WeaponIcon_LongSword_RugerAidal_SP_Water.png', 'This Ruger Aidal long sword reflects a sunlike radiance, bringing victory and joy the moment it''s drawn from its sheath. Flowing with azure prismatic light, its glow refracts as though tides surge through the radiance.', 'in_game', NULL, TRUE, FALSE, 249),
  ('101090812', 'Brilliant Hippogriff (Water)', 'Brilliant Hippogriff (Water)', '{"9":"Brilliant Hippogriff (Water)","10":"Brilliant Hippogriff (Water)","11":"Brilliant Hippogriff (Water)","12":"Brilliant Hippogriff (Water)","13":"Brilliant Hippogriff (Water)","14":"Brilliant Hippogriff (Water)"}'::JSONB, 'bow', NULL, 'Brilliant Hippogriff', 'apex_variant', 'Apex Weapon element variant: switch the element of the base version (Apex Challenge – Ruger Aidal season)', 'water', 226, 452, 0, NULL, ARRAY[1, 1]::INTEGER[], 9, 14, TRUE, TRUE, 'Apex Challenge – Ruger Aidal season', '{"name":"Bow Mastery","description":"While this weapon is equipped, damage dealt to radiant monsters increases by 8%. Each time bow energy is consumed, additional damage dealt to radiant monsters increases by 1% for the rest of the hunt, up to 3 stacks. (Season 0 only)","icon":"/images/weapons/AwakeIEntryIcon/AwakeIEntryIcon_Bow_06.png"}'::JSONB, '{"unlock_rarities":[10,11,12,13,14],"options":[["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"],["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"],["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"],["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"],["Water Damage Bonus","Affinity Bonus","Ultimate Charge Efficiency Bonus"]]}'::JSONB, '/images/weapons/WeaponIcon/Bow/WeaponIcon_Bow_RugerAidal_SP_Water.png', 'Arrows fired from this Ruger Aidal bow soar like a mythical hawk in pursuit of prey. Flowing with azure prismatic light, its glow refracts as though tides surge through the radiance.', 'in_game', NULL, TRUE, FALSE, 250),
